# S4 observation contract: expected memberships and values below are hand
# specified from small labeled trees, not generated by the observation adapter.
# The parser is used only to translate explicit node labels to public B IDs and
# to check that raw provenance points back to the actual supplied measurements.

obs_branch_ids <- function(species) {
  parsed <- SplitAlignerR:::cpp_s4_parse_tree(species, TRUE)
  keep <- nzchar(parsed$labels) & nzchar(parsed$branch_id)
  stats::setNames(parsed$branch_id[keep], parsed$labels[keep])
}

obs_order_ids <- function(ids) unname(ids[order(as.integer(sub("^B", "", ids)))])
obs_fusion_id <- function(ids) paste0("F[", paste(obs_order_ids(ids), collapse = "|"), "]")

obs_members_row <- function(ledger, members, gene = NULL) {
  keep <- vapply(ledger$primitive_members, setequal, logical(1), unname(members))
  if (!is.null(gene)) keep <- keep & ledger$gene_id == gene
  ledger[keep, , drop = FALSE]
}

obs_fusion_cell <- function(result, gene, members) {
  result$fusion_ledger[result$fusion_ledger$gene_id == gene &
    result$fusion_ledger$composite_id == obs_fusion_id(members), , drop = FALSE]
}

obs_check_raw_provenance <- function(result, genes) {
  ledger <- result$observation_ledger
  for (gene in unique(ledger$gene_id)) {
    parsed <- SplitAlignerR:::cpp_s4_parse_tree(genes[[gene]], FALSE)
    rows <- ledger[ledger$gene_id == gene, , drop = FALSE]
    # A normalized input edge belongs to one observation unit in this gene.
    # Separate target columns may nevertheless refer to this unit repeatedly.
    all_sources <- unlist(rows$input_edge_ids, use.names = FALSE)
    expect_false(anyDuplicated(all_sources) > 0L)
    for (i in seq_len(nrow(rows))) {
      ids <- rows$input_edge_ids[[i]]
      expect_true(is.integer(ids))
      expect_true(length(ids) >= 1L)
      positions <- match(ids, parsed$source_nodes)
      expect_false(anyNA(positions))
      expect_true(all(parsed$parent[positions] > 0L))
      expect_equal(rows$source_lengths[[i]], parsed$lengths[positions])
      expect_identical(rows$source_status[[i]], parsed$numeric_status[positions])
      expect_identical(rows$normalization_mode[[i]],
        if (length(ids) == 1L) "single_input_edge" else "input_edge_sum")
      if (all(parsed$numeric_status[positions] == "finite_numeric")) {
        expect_equal(rows$numeric_value[[i]], sum(parsed$lengths[positions]),
                     tolerance = 1e-12)
      } else {
        expect_true(is.na(rows$numeric_value[[i]]))
      }
    }
  }
}

test_that("T01 rooted identities and a joint unrooted measurement coexist", {
  species <- "((A:1,B:2)p:3,(C:4,D:5)q:6)r;"
  ids <- obs_branch_ids(species)
  genes <- c(g = "(A:1,B:2,(C:4,D:5):9);")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted")
  pq <- unname(ids[c("p", "q")])
  expect_identical(x$metadata$result_schema, "s4-observation-v1")
  expect_false("state_matrix" %in% names(x))
  expect_identical(unname(x$reference_state_matrix["g", pq]), rep("observed", 2L))
  expect_identical(unname(x$primitive_observation_matrix["g", pq]), rep("joint", 2L))
  expect_true(all(is.na(x$primitive_matrix["g", pq])))
  joint <- obs_members_row(x$observation_ledger, pq, "g")
  expect_equal(nrow(joint), 1L)
  expect_identical(joint$relation, "joint")
  expect_setequal(joint$reference_component_ids[[1]], pq)
  expect_equal(joint$numeric_value, 9)
  expect_equal(nrow(x$observation_ledger), 5L)
  expect_equal(nrow(x$composite_coordinates), 0L)
  expect_equal(ncol(x$fusion_matrix), 0L)
  links <- x$component_observations[x$component_observations$coordinate_id %in% pq, ]
  expect_identical(links$relation, rep("joint", 2L))
  expect_identical(unique(links$observation_id), joint$observation_id)
  expect_false(any(x$reference_state_matrix %in% c("mapped", "NA_topo", "NA_fuse_topo")))
  obs_check_raw_provenance(x, genes)
})

test_that("T02 retained ancestral stem is unrepresented, not structurally deleted", {
  species <- "((A:1,B:2)p:3,C:4)r;"
  ids <- obs_branch_ids(species)
  genes <- c(g = "(A:2,B:5);")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted")
  expect_identical(unname(x$reference_state_matrix["g", ids[["p"]]]), "observed")
  expect_identical(unname(x$reference_state_matrix["g", ids[["C"]]]), "NA_struct")
  expect_identical(unname(x$primitive_observation_matrix["g", ids[["p"]]]), "unrepresented")
  absent <- x$component_observations[x$component_observations$coordinate_id == ids[["p"]], ]
  expect_equal(nrow(absent), 1L)
  expect_identical(absent$relation, "unrepresented")
  expect_true(is.na(absent$observation_id))
  expect_true(nzchar(absent$representation_reason))
  expect_equal(nrow(x$observation_ledger), 1L)
  expect_false(any(x$observation_ledger$relation == "unrepresented"))
  expect_equal(x$observation_ledger$numeric_value, 7)
  expect_setequal(x$observation_ledger$primitive_members[[1]], unname(ids[c("A", "B")]))
  expect_true(all(is.na(x$primitive_matrix)))
  obs_check_raw_provenance(x, genes)
})

test_that("T03 explicit preserved root accepts its stem and rejects a root annotation substitute", {
  species <- "((A:1,B:2)p:3,C:4)r;"
  ids <- obs_branch_ids(species)
  genes <- c(kept = "((A:2,B:5):7);", cropped = "(A:2,B:5):13;")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted",
                            gene_semantics = "reference_rooted")
  expect_identical(rownames(x$primitive_matrix), "kept")
  expect_equal(unname(x$primitive_matrix["kept", unname(ids[c("A", "B", "p")])]), c(2, 5, 7))
  expect_identical(x$gene_outcomes$outcome, c("success", "skipped"))
  expect_identical(x$gene_outcomes$code[2], "FIXED_TOPOLOGY_MISMATCH")
  expect_true(nzchar(x$gene_outcomes$reason[2]))
  expect_identical(unname(x$reference_state_matrix["kept", ]),
                   unname(x$reference_state_matrix["cropped", ]))
  expect_true(all(x$observation_ledger$relation == "individual"))
  obs_check_raw_provenance(x, genes)
})

test_that("T04 active deletion fusion cannot take a larger joint observation", {
  species <- "(((A:1,X:2)u:3,B:4)p:5,(C:6,D:7)q:8)r;"
  ids <- obs_branch_ids(species)
  fused <- unname(ids[c("A", "u", "p")])
  joint_members <- c(fused, ids[["q"]])
  x <- align_fixed_topology(species, c(g = "(A:10,C:3,D:4);"),
                            reference_semantics = "rooted")
  expect_true(all(x$reference_state_matrix["g", fused] == "NA_fuse"))
  expect_identical(unname(x$reference_state_matrix["g", ids[["q"]]]), "observed")
  joint <- obs_members_row(x$observation_ledger, joint_members, "g")
  expect_equal(nrow(joint), 1L)
  expect_equal(joint$numeric_value, 10)
  expect_setequal(joint$reference_component_ids[[1]], c(obs_fusion_id(fused), ids[["q"]]))
  expect_true(is.na(x$primitive_matrix["g", ids[["q"]]]))
  expect_true(is.na(x$fusion_matrix["g", obs_fusion_id(fused)]))
  expect_setequal(x$composite_coordinates$coordinate_id, obs_fusion_id(fused))
  cell <- obs_fusion_cell(x, "g", fused)
  expect_equal(nrow(cell), 1L)
  expect_identical(cell$reference_state, "active")
  expect_true(is.na(cell$numeric_value))
  expect_false(cell$observation_status %in% c("individual", "recovered", "available"))
})

test_that("T05 multifurcating roots create no spurious joint units", {
  species <- "(A:1,B:2,C:3,D:4)r;"
  ids <- obs_branch_ids(species)
  x <- align_fixed_topology(species, c(full = species, pair = "(B:5,A:2);"),
                            reference_semantics = "rooted")
  full <- x$observation_ledger[x$observation_ledger$gene_id == "full", ]
  pair <- x$observation_ledger[x$observation_ledger$gene_id == "pair", ]
  expect_equal(nrow(full), 4L)
  expect_true(all(full$relation == "individual"))
  expect_equal(nrow(pair), 1L)
  expect_identical(pair$relation, "joint")
  expect_setequal(pair$primitive_members[[1]], unname(ids[c("A", "B")]))
  expect_equal(pair$numeric_value, 7)
  expect_true(all(x$reference_state_matrix["pair", unname(ids[c("A", "B")])] == "observed"))
})

test_that("T06 direct allows normalization sums and never partial or missing-source sums", {
  species <- "(A:1,B:2,C:3);"
  ids <- obs_branch_ids(species)
  genes <- c(complete = "(A:2,B:5);", zero = "(A:0,B:0);",
             missing = "(A,B:5);", marker = "(A:NA,B:5);")
  direct <- align_fixed_topology(species, genes, fusion_view = "direct")
  whole <- align_fixed_topology(species, genes, fusion_view = "whole")
  target <- obs_fusion_id(ids[c("A", "B")])
  expect_equal(unname(direct$fusion_matrix[, target]), c(7, 0, NA, NA))
  expect_equal(direct$fusion_matrix, whole$fusion_matrix)
  expect_true(all(direct$observation_ledger$normalization_mode == "input_edge_sum"))
  expect_true(all(lengths(direct$observation_ledger$input_edge_ids) == 2L))
  expect_identical(direct$gene_outcomes$outcome, rep("success", 4L))
  expect_false(any(direct$component_observations$relation == "unrepresented"))
  obs_check_raw_provenance(direct, genes)
})

test_that("T07 equal normalized lengths survive equivalent Newick roots and ordering", {
  species <- "((A:1,B:2)p:3,(C:4,D:5)q:6)r;"
  genes <- c(display_root = "((A:1,B:2):3,(C:4,D:5):6);",
             at_ab = "(A:1,B:2,(C:4,D:5):9);",
             at_cd = "(D:5,C:4,(B:2,A:1):9);")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted")
  semantic <- function(gene) {
    rows <- x$observation_ledger[x$observation_ledger$gene_id == gene, ]
    keys <- vapply(rows$primitive_members, function(z) paste(obs_order_ids(z), collapse = "|"), character(1))
    rows <- rows[order(keys), c("relation", "primitive_members", "numeric_value"), drop = FALSE]
    rownames(rows) <- NULL
    rows
  }
  expect_equal(semantic("display_root"), semantic("at_ab"))
  expect_equal(semantic("display_root"), semantic("at_cd"))
  expect_equal(unname(x$primitive_matrix[1, ]), unname(x$primitive_matrix[2, ]))
  expect_equal(unname(x$primitive_matrix[1, ]), unname(x$primitive_matrix[3, ]))
  # Raw edge IDs and the number of raw segments are legitimately different.
  expect_false(identical(x$observation_ledger$input_edge_ids[x$observation_ledger$gene_id == "display_root"],
                         x$observation_ledger$input_edge_ids[x$observation_ledger$gene_id == "at_ab"]))
  obs_check_raw_provenance(x, genes)
  rooted <- align_fixed_topology(species, c(wrong_root = genes[["at_ab"]]),
                                reference_semantics = "rooted", gene_semantics = "reference_rooted")
  expect_identical(rooted$gene_outcomes$outcome, "skipped")
})

test_that("T08 whole uses complete units and overlapping columns may reuse a unit", {
  species <- "(((A:1,B:2)u:3,C:4)p:5,(D:6,E:7)q:8)r;"
  ids <- obs_branch_ids(species)
  short <- unname(ids[c("A", "u")])
  long <- unname(ids[c("A", "u", "p")])
  genes <- c(full = species, smaller = "((A:4,C:4):5,(D:6,E:7):8);",
             long = "(A:9,(D:6,E:7):8);", deleted = "(B:10,(D:6,E:7):8);",
             missing = "(((A,B:2):3,C:4):5,(D:6,E:7):8);",
             zero = "(((A:0,B:2):0,C:4):0,(D:6,E:7):8);")
  whole <- align_fixed_topology(species, genes, reference_semantics = "rooted",
                               gene_semantics = "reference_rooted", fusion_view = "whole")
  direct <- align_fixed_topology(species, genes, reference_semantics = "rooted",
                                gene_semantics = "reference_rooted", fusion_view = "direct")
  expect_equal(unname(whole$fusion_matrix[c("full", "smaller"), obs_fusion_id(short)]), c(4, 4))
  expect_equal(unname(whole$fusion_matrix[c("full", "smaller", "long"), obs_fusion_id(long)]), c(9, 9, 9))
  expect_true(is.na(whole$fusion_matrix["long", obs_fusion_id(short)]))
  expect_true(is.na(whole$fusion_matrix["deleted", obs_fusion_id(long)]))
  expect_true(all(is.na(whole$fusion_matrix["missing", c(obs_fusion_id(short), obs_fusion_id(long))])))
  expect_equal(unname(whole$fusion_matrix["zero", c(obs_fusion_id(short), obs_fusion_id(long))]), c(0, 0))
  expect_true(is.na(direct$fusion_matrix["full", obs_fusion_id(short)]))
  expect_true(is.na(direct$fusion_matrix["smaller", obs_fusion_id(long)]))
  expect_equal(direct$fusion_matrix["smaller", obs_fusion_id(short)], 4)
  expect_equal(direct$fusion_matrix["long", obs_fusion_id(long)], 9)
  small_sources <- obs_fusion_cell(whole, "full", short)$observation_ids[[1]]
  long_sources <- obs_fusion_cell(whole, "full", long)$observation_ids[[1]]
  expect_true(length(intersect(small_sources, long_sources)) >= 1L)
  expect_false(anyDuplicated(small_sources) > 0L)
  expect_false(anyDuplicated(long_sources) > 0L)
  expect_identical(whole$reference_state_matrix, direct$reference_state_matrix)
  expect_identical(whole$component_observations, direct$component_observations)
  expect_identical(whole$observation_ledger, direct$observation_ledger)
  expect_identical(whole$gene_outcomes, direct$gene_outcomes)
  obs_check_raw_provenance(whole, genes)
})

test_that("T08 an unrepresented fused stem cannot acquire a whole value", {
  species <- "(((A:1,B:2)u:3,C:4)p:5,D:6)r;"
  ids <- obs_branch_ids(species)
  stem <- unname(ids[c("u", "p")])
  x <- align_fixed_topology(species, c(g = "(A:2,B:5);"), reference_semantics = "rooted")
  expect_true(all(x$reference_state_matrix["g", stem] == "NA_fuse"))
  expect_true(is.na(x$fusion_matrix["g", obs_fusion_id(stem)]))
  cell <- obs_fusion_cell(x, "g", stem)
  expect_identical(cell$reference_state, "active")
  expect_true(is.na(cell$numeric_value))
  expect_equal(nrow(x$observation_ledger), 1L)
  absent <- x$component_observations[x$component_observations$coordinate_id == obs_fusion_id(stem), ]
  expect_identical(absent$relation, "unrepresented")
  expect_true(is.na(absent$observation_id))
})

test_that("the shared value gate defines direct by normalized observation count", {
  # A hand-specified target tests the numerical qualification contract. This is
  # not a claim that the global deletion-fusion axis generates this target.
  # Two independent reference components are measured by one normalized unit.
  observations <- data.frame(observation_id = "O[B1|B2]",
    input_edge_ids = I(list(c(0L, 1L))), numeric_value = 7,
    numeric_status = "finite_numeric", stringsAsFactors = FALSE)
  reference_index <- list(owners = c(1L, 2L), sizes = c(1L, 1L))
  observation_index <- list(owners = c(1L, 1L), sizes = 2L)
  direct <- SplitAlignerR:::.s4_observation_cell(1:2, reference_index,
    observation_index, observations, "direct")
  expect_identical(direct$reference_state, "decomposable")
  expect_identical(direct$observation_status, "single_observation")
  expect_identical(direct$construction_mode, "single_observation_lookup")
  expect_equal(direct$numeric_value, 7)
  # The very same gate must reject assigning that joint value to primitive B1.
  primitive <- SplitAlignerR:::.s4_observation_cell(1L, reference_index,
    observation_index, observations, "whole")
  expect_identical(primitive$reference_state, "active")
  expect_identical(primitive$observation_reason, "partial_observation")
  expect_true(is.na(primitive$numeric_value))
})

test_that("T09 topology skip retains IDs, reference truth and all-skipped schema", {
  species <- "((A:1,B:2)p:3,(C:4,D:5)q:6)r;"
  genes <- c(first = "(A:1,B:2,(C:4,D:5):9);",
             bad = "(A:1,C:4,(B:2,D:5):9);", last = "(D:5,C:4,(A:1,B:2):9);")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted")
  expect_identical(rownames(x$numeric_matrix), c("first", "last"))
  expect_identical(rownames(x$reference_state_matrix), names(genes))
  expect_true(all(x$reference_state_matrix == "observed"))
  expect_identical(x$gene_outcomes$input_index, 1:3)
  expect_identical(x$gene_outcomes$gene_id, names(genes))
  expect_identical(x$gene_outcomes$outcome, c("success", "skipped", "success"))
  expect_identical(x$gene_outcomes$code[2], "FIXED_TOPOLOGY_MISMATCH")
  expect_equal(c(x$metadata$n_input, x$metadata$n_success, x$metadata$n_skipped_topology), c(3, 2, 1))
  expect_false("bad" %in% x$observation_ledger$gene_id)
  expect_false("bad" %in% x$component_observations$gene_id)
  all <- align_fixed_topology(species, genes["bad"], reference_semantics = "rooted")
  expect_identical(all$metadata$topology_status, "all_skipped")
  expect_equal(c(all$metadata$n_input, all$metadata$n_success, all$metadata$n_skipped_topology), c(1, 0, 1))
  expect_equal(nrow(all$numeric_matrix), 0L)
  expect_identical(colnames(all$primitive_matrix), x$primitive_coordinates$coordinate_id)
  expect_equal(nrow(all$observation_ledger), 0L)
  expect_equal(nrow(all$component_observations), 0L)
  expect_identical(names(all$observation_ledger), names(x$observation_ledger))
  expect_identical(vapply(all$observation_ledger, typeof, character(1)),
                   vapply(x$observation_ledger, typeof, character(1)))
  expect_output(print(all), "0.*success|success.*0|0.*matched")
})

test_that("T09 shared reference columns include a topology-skipped retained set", {
  species <- "(((A:1,B:2)u:3,C:4)p:5,(D:6,E:7)q:8)r;"
  ids <- obs_branch_ids(species)
  target <- obs_fusion_id(ids[c("A", "u")])
  genes <- c(full = species, skip = "((A:1,D:6):1,(C:4,E:7):1);")
  x <- align_fixed_topology(species, genes, reference_semantics = "rooted")
  expect_identical(x$gene_outcomes$outcome, c("success", "skipped"))
  expect_true(target %in% x$composite_coordinates$coordinate_id)
  expect_equal(x$fusion_matrix["full", target], 4)
  expect_identical(rownames(x$fusion_matrix), "full")
})

test_that("T10 parse, label, numeric and taxa errors are not topology skips", {
  species <- "((A,B),(C,D));"
  for (gene in c("(A,A,C);", "(A,Z,C);", "(A,B", "A;",
                 "(A:1e9999,B:2,C:3);", "(A:1.2junk,B:2,C:3);")) {
    expect_error(align_fixed_topology(species, gene, reference_semantics = "rooted"))
  }
  unknown <- tryCatch(align_fixed_topology(species, "(A:1,B:2,Z:3);"), error = identity)
  expect_s3_class(unknown, "splitaligner_invalid_tree")
  expect_identical(unknown$code, "UNKNOWN_TAXON")
  # NaN is an established software-failure marker, not an invalid numeric
  # token. It must preserve the match and produce a missing measurement.
  marker <- align_fixed_topology(species, c(g = "(A:NaN,B:2,C:3);"),
                                  reference_semantics = "rooted")
  expect_identical(marker$gene_outcomes$outcome, "success")
  failed <- marker$observation_ledger$numeric_status == "software_failure_marker"
  expect_equal(sum(failed), 1L)
  expect_true(is.na(marker$observation_ledger$numeric_value[failed]))
})

test_that("T11 S4 reference states equal independent S3 truth for every input", {
  species <- "(((A:1,B:2)u:3,C:4)p:5,(D:6,E:7)q:8)r;"
  genes <- c(full = species, partial = "(A:4,C:4,(D:6,E:7):13);",
             pair = "(A:2,B:5);", mismatch = "((A:1,D:6):1,(C:4,E:7):1);")
  sets <- list(full = c("A", "B", "C", "D", "E"), partial = c("A", "C", "D", "E"),
               pair = c("A", "B"), mismatch = c("A", "C", "D", "E"))
  for (semantics in c("rooted", "unrooted")) {
    s3 <- reference_truth(species, sets, tree_semantics = semantics)
    s4 <- align_fixed_topology(species, genes, reference_semantics = semantics)
    expect_identical(s4$reference_state_matrix, s3$state_matrix)
    expect_identical(s4$composite_coordinates$primitive_members,
                     s3$composite_coordinates$primitive_members)
  }
})

test_that("T12 reference lengths never control S4 identity, match or gene measurements", {
  reference <- "((A:1,B:2)p:3,(C:4,D:5)q:6)r;"
  huge_reference <- "((A:1e308,B:1e308)p:1e308,(C:1e308,D:1e308)q:1e308)r;"
  genes <- c(full = "((A:1,B:2):3,(C:4,D:5):6);", partial = "(A:2,C:5);")
  first <- align_fixed_topology(reference, genes, reference_semantics = "rooted")
  second <- align_fixed_topology(huge_reference, genes, reference_semantics = "rooted")
  for (field in c("reference_state_matrix", "primitive_observation_matrix", "primitive_matrix",
                  "fusion_matrix", "reference_components", "observation_ledger",
                  "component_observations", "gene_outcomes")) {
    expect_identical(first[[field]], second[[field]], info = field)
  }
  # Length edits in gene input change measurements, not reference identities.
  changed <- align_fixed_topology(reference, c(full = "((A:11,B:12):13,(C:14,D:15):16);",
                                              partial = "(A:12,C:15);"),
                                 reference_semantics = "rooted")
  expect_identical(first$reference_state_matrix, changed$reference_state_matrix)
  expect_identical(first$primitive_observation_matrix, changed$primitive_observation_matrix)
  expect_identical(first$component_observations, changed$component_observations)
  expect_identical(first$gene_outcomes, changed$gene_outcomes)
  expect_false(identical(first$observation_ledger$numeric_value, changed$observation_ledger$numeric_value))
})

test_that("legacy rooted arguments cannot silently change coordinate identity", {
  species <- "((A,B),(C,D));"
  gene <- "(A:1,B:2,(C:3,D:4):5);"
  expect_error(align_fixed_topology(species, gene, tree_semantics = "rooted"),
               "rooted|migrat|preserv")
  expect_warning(old <- align_fixed_topology(species, gene, tree_semantics = "unrooted"),
                 "tree_semantics|deprecat")
  current <- align_fixed_topology(species, gene)
  expect_identical(old$reference_state_matrix, current$reference_state_matrix)
  expect_equal(old$numeric_matrix, current$numeric_matrix)
  expect_error(align_fixed_topology(species, gene, tree_semantics = "unrooted",
                                   reference_semantics = "unrooted"), "mix|both|together|tree_semantics")
  expect_error(align_fixed_topology(species, gene, gene_semantics = "reference_rooted"),
               "rooted|reference")
})
